function outlineText(cid) {
var c = null;
S.courses.forEach(function (x) { if (x.uid === cid) c = x; });
if (!c) return '';
var out = [c.name, ''], by = {}, order = [];
S.items.forEach(function (it) {
if (it.cid !== cid) return;
if (!by[it.sec]) { by[it.sec] = []; order.push(it.sec); }
by[it.sec].push(it);
});
order.forEach(function (sec) {
out.push(sec);
by[sec].forEach(function (it) {
var f = (it.files || [])[0];
out.push('  ' + tname(it.mod) + ': ' + it.name + (f ? ' (' + f.nm + ')' : ''));
});
out.push('');
});
return out.join('\n');
}
function copyOutline(cid) {
var t = outlineText(cid);
if (!t) return;
if (navigator.clipboard) {
navigator.clipboard.writeText(t).then(function () { alert('מבנה הקורס הועתק. אפשר להדביק אותו בכל מקום.'); },
function () { window.prompt('העתק את הטקסט', t); });
} else { window.prompt('העתק את הטקסט', t); }
}
function clean(s) {
return String(s).replace(/[\\/:*?"<>|]/g, '-').replace(/\s+/g, ' ').trim().slice(0, 70);
}
function downloadCourse(cid) {
var c = null;
S.courses.forEach(function (x) { if (x.uid === cid) c = x; });
if (!c) return;
var jobs = [];
S.items.forEach(function (it) {
if (it.cid !== cid) return;
(it.files || []).forEach(function (f) {
jobs.push({ href: f.href, name: clean(c.name) + ' - ' + clean(it.name) + ' - ' + f.nm });
});
});
if (!jobs.length) { alert('לא נמצאו קבצים בקורס הזה.'); return; }
if (!confirm('להוריד ' + nFiles(jobs.length) + ' מהקורס ' + c.name + '?\nהדפדפן יבקש ממך פעם אחת לאשר הורדה של כמה קבצים.')) return;
var k = 0;
(function next() {
if (k >= jobs.length) return;
var j = jobs[k++];
var a = document.createElement('a');
a.href = j.href; a.download = j.name; a.style.display = 'none';
document.body.appendChild(a); a.click(); a.remove();
setTimeout(next, 420);
})();
}
